import React, { ChangeEvent, ReactNode, useCallback, useId } from 'react';
import * as S from './styles';
import { InputLabel, TProps as TInputLabelProps } from '../InputLabel';
import { PureInput, TProps as TPureInputProps } from '../PureInput';
import { useInputFocus } from '../../../hooks/useInputFocus';
import { TSizes } from '../constants';
import { useInputStyles } from '../_hooks/useInputStyles';
import { useElementWidth } from '../_hooks/useElementWidth';

const CHILDREN_RIGHT_OFFSET = 12;
const CHILDREN_GAP = 8;

export type TProps = Pick<TInputLabelProps, 'label' | 'required'> &
    Pick<
        TPureInputProps,
        | 'placeholder'
        | 'hasError'
        | 'onFocus'
        | 'onBlur'
        | 'disabled'
        | 'name'
        | 'paddingRight'
        | 'type'
        | 'isOnlyNumbers'
        | 'autoFocus'
        | 'rows'
        | 'id'
        | 'useModernStyles'
        | 'readOnly'
        | 'inputMode'
        | 'autoComplete'
    > & {
        value: string;
        onChange: (value: string) => void;
        maxLength?: number;
        size?: TSizes;
        children?: ReactNode;
        element?: 'input' | 'textarea';
        required?: boolean;
    };

export const TextInput = React.forwardRef<HTMLInputElement, TProps>(
    (
        {
            hasError = false,
            onFocus,
            onBlur,
            value,
            onChange,
            label,
            name,
            maxLength,
            disabled,
            placeholder,
            paddingRight,
            type,
            children,
            size,
            isOnlyNumbers,
            autoFocus,
            element = 'input',
            rows,
            required = false,
            useModernStyles = false,
            id,
            inputMode,
            readOnly,
            autoComplete,
        },
        ref,
    ) => {
        const { inFocus, handleFocus, handleBlur } = useInputFocus({ onFocus, onBlur });

        const fallbackId = useId();
        const inputId = id ?? fallbackId;

        const { ref: childrenRef, width: childrenWidth } = useElementWidth<HTMLDivElement>();

        const placeholderPaddingRight = childrenWidth
            ? childrenWidth + CHILDREN_RIGHT_OFFSET + CHILDREN_GAP
            : paddingRight;

        const { inputLabel, paddingAndVariantOptions, modernPlaceholder, fieldSize } = useInputStyles({
            isHaveValue: !!value,
            useModernStyles,
            size,
            label,
            inFocus,
            placeholder,
            required,
            paddingRight: placeholderPaddingRight,
        });

        const handleChange = useCallback(
            (event: ChangeEvent<HTMLInputElement>) => {
                onChange(event.target.value.slice(0, maxLength ?? Infinity));
            },
            [onChange, maxLength],
        );

        return (
            <InputLabel
                inFocus={inFocus}
                label={inputLabel}
                disabled={disabled}
                required={required}
                size={fieldSize}
                useModernStyles={useModernStyles}
                htmlFor={inputId}
            >
                <S.InputLabelContent>
                    {modernPlaceholder}
                    <PureInput
                        id={inputId}
                        aria-label={label && !inputLabel ? label : undefined}
                        ref={ref}
                        name={name}
                        disabled={disabled}
                        hasError={hasError}
                        inFocus={inFocus}
                        onFocus={handleFocus}
                        onBlur={handleBlur}
                        value={value}
                        onChange={handleChange}
                        placeholder={useModernStyles ? undefined : placeholder}
                        paddingRight={paddingRight}
                        type={type}
                        isOnlyNumbers={isOnlyNumbers}
                        // eslint-disable-next-line jsx-a11y/no-autofocus -- проп прокидывается потребителю, решение об автофокусе за ним
                        autoFocus={autoFocus}
                        element={element}
                        rows={rows}
                        useModernStyles={useModernStyles}
                        inputMode={inputMode}
                        readOnly={readOnly}
                        autoComplete={autoComplete}
                        {...paddingAndVariantOptions}
                    />
                    {children && <S.ChildrenWrapper ref={childrenRef}>{children}</S.ChildrenWrapper>}
                </S.InputLabelContent>
            </InputLabel>
        );
    },
);

TextInput.displayName = 'TextInput';
